use std::fs

fn all_digits(s: string, n: int) -> bool {
    if s.len() as int != n {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

// returns days since 1970-01-01, or -1000000 if invalid
fn parse_date(s: string) -> int {
    let bad = -1000000
    let parts: Vec<string> = s.split("-").collect()
    if parts.len() as int != 3 {
        return bad
    }
    if !all_digits(parts[0], 4) || !all_digits(parts[1], 2) || !all_digits(parts[2], 2) {
        return bad
    }
    let y: int = parts[0].parse::<int>().unwrap_or(0)
    let m: int = parts[1].parse::<int>().unwrap_or(0)
    let d: int = parts[2].parse::<int>().unwrap_or(0)
    if y < 1900 || y > 2100 || m < 1 || m > 12 || d < 1 {
        return bad
    }
    let mut dim = 31
    if m == 4 || m == 6 || m == 9 || m == 11 {
        dim = 30
    } else if m == 2 {
        dim = if is_leap(y) { 29 } else { 28 }
    }
    if d > dim {
        return bad
    }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let names = ["Thursday", "Friday", "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday"]
    for line in text.lines() {
        let toks: Vec<string> = line.split_whitespace().collect()
        if toks.len() as int == 0 {
            continue
        }
        if toks.len() as int != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(toks[0])
        let b = parse_date(toks[1])
        if a == -1000000 || b == -1000000 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let w = ((lo % 7) + 7) % 7
        println("${diff} ${names[w as usize]}")
    }
}

